import{_ as n,a0 as p,w as a,s as l,ao as T,I as o,x as e,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"为什么计量 IT 的生产力如此具有挑战性？ | LCTT x X-CMD","titleTemplate":false,"description":"为什么计量 IT 的生产力如此具有挑战性？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么计量 IT 的生产力如此具有挑战性？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么计量 IT 的生产力如此具有挑战性？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160808 Why measuring IT productivity is so challenging","title":"为什么计量 IT 的生产力如此具有挑战性？","tag":"201609","desc":""},"relativePath":"201609/20160808 Why measuring IT productivity is so challenging.md","filePath":"[post].md"}'),m={name:"201609/20160808 Why measuring IT productivity is so challenging.md"};function u(d,t,g,I,f,C){const r=p("Link");return a(),l("div",null,[t[15]||(t[15]=T('<h1 id="为什么计量-it-的生产力如此具有挑战性" tabindex="-1">为什么计量 IT 的生产力如此具有挑战性？ <a class="header-anchor" href="#为什么计量-it-的生产力如此具有挑战性" aria-label="Permalink to “为什么计量 IT 的生产力如此具有挑战性？”">​</a></h1><p><img src="https://enterprisersproject.com/sites/default/files/styles/620x350/public/images/cio_talent_6.png?itok=JV-zSor3" alt=""></p><p>在某些行业里，人们可以根据一些测量标准判定一个人的生产力。比如，如果你是一个零件制造商，可以通过一个月你能够制造的零件数量来确定你的生产效率。如果你在客户服务中心工作，你解答了多少个客户来电，你的平均解答时间都会成为评判你的生产效率的依据。这些都是相当简单的案例，但即便你是一位医生，也可以通过你主刀的临床手术次数或者一个月你确诊的患者数量来确定你的生产效率。无论这些评判标准正确与否，但它们提供了一个通用的方法来评断一个人在给定时间内的执行能力。</p><p>然而在 IT 这方面，通过上述方法来衡量一个人的生产力是不可能的，因为 IT 有太多的变化性。比如，通过一个开发者编写的代码行数来衡量开发者所用的时间看起来很诱人。但是，编程的语言很大程度上能影响到根据这种方法得到的结论。因为一种编程语言的一行代码比用其他编程语言编写所花费的时间和难度可能会明显的多或少。</p><p>它总是这样不可捉摸吗？多年以前，你可能听说过或者经历过根据功能点来衡量 IT 工作人员的生产效率。这些措施是针对开发者们能够创建的关键特征来衡量开发者的生产效率的。但这种方法在今天也变得逐渐难以实施，开发者经常将可能已有的逻辑封装进内部，比如，按供应商来整合功能点。这使得仅仅是基于功能点的数目来估量生产效率难度加大。</p><p>这两个例子能够阐述为什么当我们 CIO 之间谈论 IT 生产效率的时候有时会引起争论。考虑以下这个假想中的谈话：</p><blockquote><p>IT leader：“天啊，我想这些开发者一定很厉害。”<br> HR：“真的假的，他们做了什么？”<br> IT leader：“他们做了个相当好的应用。” HR：“好吧，那他们比那些做了 10 个应用的开发者更好吗” IT leader：“这要看你怎么理解 ‘更好’。”</p></blockquote><p>这个对话比较有代表性。当我们处于上述的这种交谈时，这里面有太多的主观因素导致我们很难回答这个问题。当我们用一种有意义的方法来测试 IT 的效率时，类似上述谈话的这种问题仅仅是冰山一角。这不仅仅使谈话更加困难－它还会使 CIO 们很难展示他们的团队在商业上的价值。</p><p>确实这不是一个新出现的问题。我已经花费差不多 30 年的时间来思考这个问题。我得出的结论是我们真的不应该在谈论 IT 的生产效率这件事上面相互烦扰－因为我们永远不可能有结论。</p><p>我认为我们需要在改变这种对话同时停止根据生产能力和成本来谈论 IT 的生产效率，将目光集中于衡量 IT 的整体商业价值上。重申一下，这个过程不会很容易。商业价值的实现是一件困难的事情。但如果 CIO 们能够和商业人员合作来解决这个问题，就可以将实际价值变的更加科学而非一种艺术形式。</p><hr>',11)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),i(r,{href:"https://enterprisersproject.com/article/2016/8/why-measuring-it-productivity-so-challenging"},{default:s(()=>[...t[0]||(t[0]=[e("https://enterprisersproject.com/article/2016/8/why-measuring-it-productivity-so-challenging",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=e("作者：",-1)),i(r,{href:"https://enterprisersproject.com/user/anil-cheriyan"},{default:s(()=>[...t[2]||(t[2]=[e("Anil Cheriyan",-1)])]),_:1}),t[7]||(t[7]=e(" 译者：",-1)),i(r,{href:"https://github.com/LemonDemo"},{default:s(()=>[...t[3]||(t[3]=[e("LemonDemo",-1)])]),_:1}),t[8]||(t[8]=e("　",-1)),i(r,{href:"https://github.com/WangYueScream"},{default:s(()=>[...t[4]||(t[4]=[e("WangYueScream",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),i(r,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const L=n(m,[["render",u]]);export{h as __pageData,L as default};
